#include <list>
#include <iostream>

void list_operations(std::list<int>& l) noexcept {
    // These operations are guaranteed not to throw, 
    // provided element destruction (which happens internally)
    // is also non-throwing.

    l.pop_back(); 
    l.erase(l.begin());

    std::list<int> temp = {10, 20};
    // Splice is guaranteed no-throw, only pointer manipulation
    l.splice(l.end(), temp);

    // l.clear(); // Also no-throw
}
